-- AXIVESTRA RBAC hardening follow-up migration.
-- Keep this separate from 001 so a project that already applied an earlier 001
-- can upgrade triggers/grants without editing migration history.
alter table public.company_records add column if not exists deleted_at timestamptz;

-- Audit governance events are server-generated by the membership trigger, never client-authored.
drop policy if exists "members can append audit events" on public.company_audit_events;
revoke all on table public.company_audit_events from anon, authenticated;
grant select on table public.company_audit_events to authenticated;

-- Clients use soft-delete tombstones; direct physical deletes bypass restoration safeguards.
revoke delete on table public.company_records from authenticated;
grant select, insert, update on table public.company_records to authenticated;

-- Keep a trustworthy actor ID for membership changes made via the server-side invite function.
alter table public.company_memberships add column if not exists updated_by uuid references auth.users(id) on delete set null;

create or replace function public.guard_company_record_identity()
returns trigger
language plpgsql
security definer
set search_path = ''
as $axivestra$
begin
  if tg_op = 'INSERT' then
    if auth.uid() is null then
      raise exception 'Authenticated user context is required to create a company record.';
    end if;
    new.created_by := auth.uid();
    new.updated_by := auth.uid();
    return new;
  end if;

  if old.company_id is distinct from new.company_id
     or old.record_type is distinct from new.record_type
     or old.record_key is distinct from new.record_key then
    raise exception 'Company, record type and record key are immutable. Create a new scoped record instead.';
  end if;
  new.created_by := old.created_by;
  return new;
end;
$axivestra$;

drop trigger if exists company_records_identity_guard on public.company_records;
create trigger company_records_identity_guard
before insert or update on public.company_records
for each row execute function public.guard_company_record_identity();

-- Membership identity is immutable: a role administrator cannot silently
-- transfer an existing membership to another user or company.
create or replace function public.guard_company_membership_identity()
returns trigger
language plpgsql
set search_path = ''
as $axivestra$
begin
  if old.company_id is distinct from new.company_id
     or old.user_id is distinct from new.user_id then
    raise exception 'Company and user IDs on an existing membership are immutable.';
  end if;
  return new;
end;
$axivestra$;

drop trigger if exists company_membership_identity_guard on public.company_memberships;
create trigger company_membership_identity_guard
before update on public.company_memberships
for each row execute function public.guard_company_membership_identity();

-- A company can be renamed by an owner/admin, but its ID and creator cannot be rewritten.
create or replace function public.guard_company_identity()
returns trigger
language plpgsql
set search_path = ''
as $axivestra$
begin
  if old.id is distinct from new.id or old.created_by is distinct from new.created_by then
    raise exception 'Company ID and creator are immutable.';
  end if;
  return new;
end;
$axivestra$;

drop trigger if exists company_identity_guard on public.companies;
create trigger company_identity_guard
before update on public.companies
for each row execute function public.guard_company_identity();

create or replace function public.guard_company_membership_actor()
returns trigger
language plpgsql
security definer
set search_path = ''
as $axivestra$
begin
  if auth.uid() is not null then
    if tg_op = 'INSERT' then
      new.created_by := auth.uid();
    end if;
    new.updated_by := auth.uid();
  else
    -- Service-role invitation requests must explicitly identify the verified caller.
    new.updated_by := coalesce(new.updated_by, new.created_by);
  end if;
  return new;
end;
$axivestra$;

drop trigger if exists company_membership_actor_guard on public.company_memberships;
create trigger company_membership_actor_guard
before insert or update on public.company_memberships
for each row execute function public.guard_company_membership_actor();

create or replace function public.log_company_membership_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $axivestra$
declare
  actor_id uuid;
  target_company_id uuid;
  target_user_id uuid;
  action_name text;
  action_label text;
begin
  if tg_op = 'INSERT' then
    target_company_id := new.company_id;
    target_user_id := new.user_id;
    actor_id := coalesce(auth.uid(), new.updated_by, new.created_by);
    action_name := 'member_added';
    action_label := 'Company membership created with role ' || new.role;
  elsif tg_op = 'UPDATE' then
    if old.role is not distinct from new.role then return new; end if;
    target_company_id := new.company_id;
    target_user_id := new.user_id;
    actor_id := coalesce(auth.uid(), new.updated_by, new.created_by, old.created_by);
    action_name := 'member_role_changed';
    action_label := 'Company membership role changed to ' || new.role;
  else
    target_company_id := old.company_id;
    target_user_id := old.user_id;
    actor_id := coalesce(auth.uid(), old.updated_by, old.created_by);
    action_name := 'member_removed';
    action_label := 'Company membership removed';
  end if;

  if actor_id is not null then
    insert into public.company_audit_events(
      company_id, actor_user_id, action, entity_type, entity_key, label
    ) values (
      target_company_id, actor_id, action_name, 'membership', target_user_id::text, action_label
    );
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$axivestra$;

drop trigger if exists company_membership_audit on public.company_memberships;
create trigger company_membership_audit
after insert or update or delete on public.company_memberships
for each row execute function public.log_company_membership_change();

revoke all on function public.guard_company_record_identity() from public;
revoke all on function public.guard_company_membership_identity() from public;
revoke all on function public.guard_company_identity() from public;
revoke all on function public.guard_company_membership_actor() from public;
revoke all on function public.guard_company_record_soft_delete() from public;
revoke all on function public.log_company_membership_change() from public;
